const input = $input.first();
const raw = input.json || {};
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const binaries = input.binary || {};
const binaryKey = binaries.file ? 'file' : Object.keys(binaries)[0];

if (!binaryKey || !binaries[binaryKey]) {
  throw new Error('O Sistema LEME não enviou o arquivo binário.');
}

const folderId = String(body.folder_id || '').trim();
if (!/^[A-Za-z0-9_-]{10,}$/.test(folderId)) {
  throw new Error('ID da pasta do Google Drive inválido.');
}

const original = binaries[binaryKey];
const fallbackName = String(original.fileName || 'Arte LEME').trim();
const requestedName = String(body.file_name || fallbackName).trim();
const fileName = (requestedName || fallbackName).replace(/[\/]+/g, ' - ').slice(0, 220);
const expectedSize = Number(body.file_size || 0);

const file = { ...original, fileName };
if (body.mime_type) file.mimeType = String(body.mime_type);

return [{
  json: {
    folder_id: folderId,
    folder_url: String(body.folder_url || ''),
    file_name: fileName,
    relative_path: String(body.relative_path || fileName),
    mime_type: String(body.mime_type || file.mimeType || 'application/octet-stream'),
    expected_size: Number.isFinite(expectedSize) ? expectedSize : 0,
    post_id: String(body.post_id || ''),
    post_title: String(body.post_title || ''),
    publication_date: String(body.publication_date || ''),
    publication_format: String(body.publication_format || ''),
    collaborator_id: String(body.collaborator_id || ''),
    source: String(body.source || 'sistema_leme'),
    export_version: String(body.export_version || ''),
    file_index: Number(body.file_index || 1),
    file_total: Number(body.file_total || 1)
  },
  binary: { file }
}];
